// Thin postMessage bridge: runs inside the FreeCut iframe.
// Receives assets from Cine Studio and notifies it of exports.

export type StudioAsset = {
  id: string
  name: string
  type: 'video' | 'image' | 'audio'
  url: string
  duration?: number
}

export type StudioIncomingMessage =
  | { type: 'STUDIO_HANDSHAKE' }
  | { type: 'STUDIO_ASSETS'; assets: StudioAsset[] }

export type FreeCutOutgoingMessage =
  | { type: 'FREECUT_READY' }
  | { type: 'FREECUT_EXPORT_DONE'; filename: string }

const importedStudioAssetIds = new Set<string>()
const PROJECT_READY_RETRY_COUNT = 20
const PROJECT_READY_RETRY_DELAY_MS = 250

function postToParent(msg: FreeCutOutgoingMessage) {
  if (window.parent !== window) {
    window.parent.postMessage(msg, '*')
  }
}

function isStudioMessage(data: unknown): data is StudioIncomingMessage {
  return (
    typeof data === 'object' &&
    data !== null &&
    'type' in data &&
    typeof (data as { type: unknown }).type === 'string' &&
    ((data as { type: string }).type === 'STUDIO_HANDSHAKE' ||
      (data as { type: string }).type === 'STUDIO_ASSETS')
  )
}

function delay(ms: number) {
  return new Promise<void>((resolve) => {
    window.setTimeout(resolve, ms)
  })
}

async function getMediaLibraryStoreWhenReady() {
  const { useMediaLibraryStore } = await import(
    '@/features/media-library/stores/media-library-store'
  )

  for (let attempt = 0; attempt <= PROJECT_READY_RETRY_COUNT; attempt += 1) {
    const store = useMediaLibraryStore.getState()
    if (store.currentProjectId) {
      return store
    }
    await delay(PROJECT_READY_RETRY_DELAY_MS)
  }

  return null
}

async function importAssetsIntoFreeCut(assets: StudioAsset[]) {
  console.log('[FreeCut Bridge] Assets received from Cine Studio:', assets)

  const store = await getMediaLibraryStoreWhenReady()
  if (!store) {
    console.warn('[FreeCut Bridge] Media library project is not ready; assets were not imported')
    return
  }

  for (const asset of assets) {
    if (importedStudioAssetIds.has(asset.id)) {
      continue
    }

    const imported = await store.importMediaFromUrl(asset.url)
    if (imported.length > 0) {
      importedStudioAssetIds.add(asset.id)
    }
  }
}

export function initBridgeClient() {
  if (window.parent === window) {
    return
  }

  window.addEventListener('message', (event: MessageEvent) => {
    if (!isStudioMessage(event.data)) {
      return
    }

    const msg = event.data

    if (msg.type === 'STUDIO_HANDSHAKE') {
      postToParent({ type: 'FREECUT_READY' })
      return
    }

    if (msg.type === 'STUDIO_ASSETS') {
      importAssetsIntoFreeCut(msg.assets).catch(console.error)
    }
  })

  postToParent({ type: 'FREECUT_READY' })
}
